    "questionEnglish": "Match the structural preposition categories with their respective examples:",
    "explanation": "Prepositions are structurally classified into four categories. (1) Simple Prepositions consist of a single word — examples: in, on, at, by, for, from, of, to, with, through. (2) Compound Prepositions are formed by prefixing a preposition to a noun, adjective, or adverb — examples: beneath (be + neath), about, above, across, behind, within. (3) Phrase Prepositions are groups of words functioning as a single preposition — examples: by virtue of, in spite of, on account of, in front of. (4) Participle Prepositions are participles used as prepositions — examples: considering, regarding, concerning, during, notwithstanding. So Through → Simple, Beneath → Compound, By virtue of → Phrase, Considering → Participle. Correct match: 1-K, 2-J, 3-M, 4-L.",
