    "questionType": "mcq",
    "explanation": "Cases in English are determined by syntactic role. (1) Nominative — subject of a verb. (2) Genitive — possession. (3) Accusative (Objective) — object of a verb or preposition. (4) Vocative — direct address. In 'There is a cow in the field', 'the field' is the object of the preposition 'in'. Objects of prepositions always take the Accusative (Objective) Case. Answer: Accusative.",
